'use strict';
(async()=>{
 const form=document.querySelector('#report-form'),status=document.querySelector('#form-status'),submit=document.querySelector('#report-submit');let widget;
 const params=new URLSearchParams(location.search);const id=params.get('offer');if(id&&/^[a-z0-9][a-z0-9-]{2,59}$/.test(id)){form.offer_id.value=id;form.page_path.value='/offers/'+id;}
 try{
  const response=await fetch('/api/config',{cache:'no-store'});if(!response.ok)throw Error();const config=await response.json();
  window.fluqonReportReady=()=>{widget=window.turnstile.render('#security-check',{sitekey:config.sitekey,theme:'dark',action:'report',callback:()=>{submit.disabled=false;status.textContent='Ready when you are.';},'expired-callback':()=>{submit.disabled=true;status.textContent='Security check expired. Complete it again.';},'error-callback':()=>{submit.disabled=true;status.textContent='Security check could not load. Try refreshing, or email sayvon@fluqon.qpon.';}});status.textContent='Complete the security check, then send your report.';};
  const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=fluqonReportReady&render=explicit';script.onerror=()=>{status.textContent='Security check unavailable. Email sayvon@fluqon.qpon instead.';};document.head.append(script);
 }catch{status.textContent='Reports are temporarily unavailable. Email sayvon@fluqon.qpon instead.';}
 form.addEventListener('submit',async event=>{event.preventDefault();let pagePath;try{const raw=form.page_path.value.trim();const link=new URL(raw.startsWith('/')?raw:raw.startsWith('fluqon.qpon/')?'https://'+raw:raw,'https://fluqon.qpon');if(link.origin!=='https://fluqon.qpon'||!/^\/[a-zA-Z0-9/_-]*$/.test(link.pathname)||link.pathname.length>180)throw Error();pagePath=link.pathname;}catch{status.textContent='Use a fluqon.qpon page link, such as https://fluqon.qpon/about or /about.';form.page_path.focus();return;}submit.disabled=true;status.textContent='Sending report…';try{const response=await fetch('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer_id:pagePath.match(/^\/offers\/([a-z0-9][a-z0-9-]{2,59})$/)?.[1]||'',page_path:pagePath,reason:form.reason.value,details:form.details.value,turnstile:window.turnstile.getResponse(widget)})});const result=await response.json();if(!response.ok)throw Error(result.error);document.querySelector('#report-receipt').textContent=result.message+' Reference: '+result.reference;status.textContent='You can send another report after a fresh security check.';form.details.value='';}catch(error){status.textContent=error.message||'Report could not be sent. Try again.';}finally{window.turnstile?.reset(widget);}});
})();
